import{_ as t,Y as o,o as n,c as i,aq as r,H as s}from"./chunks/framework.DBeWS8RL.js";import"./chunks/theme.CKVSPiTA.js";const b=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/home.md","filePath":"en/guide/home.md"}'),l={name:"en/guide/home.md"};function u(c,e,d,h,p,f){const a=o("NolebaseGitChangelog");return n(),i("div",null,[e[0]||(e[0]=r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><blockquote><p><code>KavaRef</code> is a modern Java reflection API implemented using Kotlin.</p></blockquote><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>This is a modern Java reflection API implemented using Kotlin, designed to provide a cleaner and easier-to-use API while retaining the power of Java reflection.</p><p>The project icon is designed by <a href="https://github.com/Lagrio" target="_blank" rel="noreferrer">MaiTungTM</a> and is named from <strong>K</strong>otlinJ<strong>avaRef</strong>lection, meaning Java reflection implemented using Kotlin.</p><p>It was first born in the <a href="https://github.com/HighCapable/YukiHookAPI" target="_blank" rel="noreferrer">YukiHookAPI</a>, and was later decoupled into the <a href="https://github.com/HighCapable/YukiReflection" target="_blank" rel="noreferrer">YukiReflection</a> project.</p><p>As you can see, KavaRef is an entirely new API set refactored around the design principles of YukiReflection. It carries no affiliation and has officially replaced YukiReflection as the new reflection solution.</p><p>If you are using YukiReflection or the YukiHookAPI project related to it, you can refer to <a href="./../config/migration.html">here</a> to migrate the reflection API to KavaRef.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>KavaRef is built with Kotlin <strong>lambda</strong> syntax in a Java Builder style.</p><p>It can replace <a href="https://www.oracle.com/technical-resources/articles/java/javareflection.html" target="_blank" rel="noreferrer">Java&#39;s native Reflection API</a> and implement a more complete reflection solution with a more human-friendly language.</p><h2 id="skill-requirements" tabindex="-1">Skill Requirements <a class="header-anchor" href="#skill-requirements" aria-label="Permalink to &quot;Skill Requirements&quot;">​</a></h2><p>You should be proficient with Java&#39;s native reflection APIs, understand Java&#39;s class loading mechanisms, bytecode structures, and how they are used in Kotlin (if you are using Kotlin).</p><h2 id="language-requirement" tabindex="-1">Language Requirement <a class="header-anchor" href="#language-requirement" aria-label="Permalink to &quot;Language Requirement&quot;">​</a></h2><p>It is recommended to use Kotlin. API composition also supports Java, but in pure Java projects, KavaRef may not be able to demonstrate its full functionality and syntactic sugar advantages.</p><p>All the demo sample code in the documentation will be described using Kotlin first. If you don&#39;t know how to use Kotlin at all, you may not be able to fully experience and use the functionality of KavaRef.</p><h2 id="contribution" tabindex="-1">Contribution <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;Contribution&quot;">​</a></h2><p>The maintenance of this project is inseparable from the support and contributions of all developers.</p><p>This project is currently in its early stages, and there may still be some problems or lack of functions you need.</p><p>If possible, feel free to submit a PR to contribute features you think are needed to this project or go to <a href="https://github.com/HighCapable/KavaRef/issues" target="_blank" rel="noreferrer">GitHub Issues</a> to make suggestions to us.</p>',20)),s(a)])}const k=t(l,[["render",u]]);export{b as __pageData,k as default};
